            active: bson_values::read(document, "active", bson_values::as_bool)?,
            address: bson_values::read(document, "address", bson_values::as_nested(CustomerAddress::from_document))?,
            tags: bson_values::read(document, "tags", bson_values::as_list(bson_values::as_text))?,
            seen: bson_values::read(document, "seen", bson_values::as_moment)?,
            r#ref: bson_values::read(document, "ref", bson_values::as_uuid)?,
            photo: bson_values::read(document, "photo", bson_values::as_bytes)?,
            scores: bson_values::read(document, "scores", bson_values::as_any)?,
