        bson_values::write(&mut document, "address", &self.address, bson_values::of_nested(CustomerAddress::to_document))?;
        bson_values::write(&mut document, "tags", &self.tags, bson_values::of_list(bson_values::of_text))?;
        bson_values::write(&mut document, "seen", &self.seen, bson_values::of_moment)?;
        bson_values::write(&mut document, "ref", &self.r#ref, bson_values::of_uuid)?;
        bson_values::write(&mut document, "photo", &self.photo, bson_values::of_bytes)?;
        bson_values::write(&mut document, "scores", &self.scores, bson_values::of_any)?;
