/// Where orders rows are kept. Services depend only on this trait.
#[async_trait]
pub trait OrderRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_id(&self, id: String) -> Result<Option<Order>, DomainError>;

    /// At most limit rows from offset, by primary key, and how many there are.
    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Order>, DomainError>;

    /// Rows with this customer, by primary key.
    async fn list_by_customer(&self, customer: String) -> Result<Vec<Order>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Order) -> Result<Order, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Order) -> Result<Order, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Order) -> Result<(), DomainError>;

    /// Adds an item to lines, and gives the row as it is then, if there is one.
    async fn add_line(&self, id: String, line: crate::entities::order::OrderLine) -> Result<Option<Order>, DomainError>;

    /// Removes an item from lines, and gives the row as it is then, if there is one.
    async fn remove_line(&self, id: String, line_id: String) -> Result<Option<Order>, DomainError>;
}

/// Keeps orders rows in the database, through the MongoDB driver: on the connection of the unit of work, or in its transaction.
pub struct MongoOrderRepository<'a> {
    db: &'a Db,
}

impl<'a> MongoOrderRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl OrderRepository for MongoOrderRepository<'_> {
    async fn find_by_id(&self, id: String) -> Result<Option<Order>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let found = self.db.find_one("orders", doc! { "_id": bson_values::of_object_id(&id)? }).await?;
        Ok(found.as_ref().map(Order::from_document).transpose()?)
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Order>, DomainError> {
        let total = self.db.count("orders", doc! {}).await?;
        let found = if limit > 0 {
            self.db.find("orders", doc! {}, doc! { "_id": 1 }, offset, limit).await?
        } else {
            Vec::new()
        };
        Ok(Page { items: found.iter().map(Order::from_document).collect::<Result<_, _>>()?, total, offset, limit })
    }

    async fn list_by_customer(&self, customer: String) -> Result<Vec<Order>, DomainError> {
        if !bson_values::is_object_id(&customer) {
            return Ok(Vec::new());
        }
        let found = self.db.find("orders", doc! { "customer": bson_values::of_object_id(&customer)? }, doc! { "_id": 1 }, 0, 0).await?;
        Ok(found.iter().map(Order::from_document).collect::<Result<_, _>>()?)
    }

    async fn insert(&self, entity: Order) -> Result<Order, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        entity.identify_items();
        let document = entity.to_document()?;
        self.db.insert("Order", "orders", &document).await?;
        entity.loaded_document = Loaded(Some(document));
        Ok(entity)
    }

    async fn update(&self, entity: Order) -> Result<Order, DomainError> {
        let mut entity = entity;
        entity.identify_items();
        let now = entity.to_document()?;
        let changes = bson_values::changes(entity.loaded_document.0.as_ref(), &now, &["number", "customer", "seller", "lines"]);
        if !changes.is_empty() {
            self.db.update("Order", "orders", doc! { "_id": now.get("_id").cloned() }, changes).await?;
        }
        entity.loaded_document = Loaded(Some(now));
        Ok(entity)
    }

    async fn delete(&self, entity: &Order) -> Result<(), DomainError> {
        let id = entity.id.clone().expect("id is set");
        self.db.delete("Order", "orders", doc! { "_id": bson_values::of_object_id(&id)? }).await
    }

    async fn add_line(&self, id: String, line: crate::entities::order::OrderLine) -> Result<Option<Order>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let mut line = line;
        line.id = line.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        let change = doc! { "$push": { "lines": bson_values::of_nested(crate::entities::order::OrderLine::to_document)(&line)? } };
        let changed = self.db.change("Order", "orders", doc! { "_id": bson_values::of_object_id(&id)? }, change).await?;
        Ok(changed.as_ref().map(Order::from_document).transpose()?)
    }

    async fn remove_line(&self, id: String, line_id: String) -> Result<Option<Order>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        if !bson_values::is_object_id(&line_id) {
            return Ok(None);
        }
        let change = doc! { "$pull": { "lines": { "_id": bson_values::of_object_id(&line_id)? } } };
        let changed = self.db.change("Order", "orders", doc! { "_id": bson_values::of_object_id(&id)? }, change).await?;
        Ok(changed.as_ref().map(Order::from_document).transpose()?)
    }
}

