//! The service of the "customers" table.

use crate::common::Page;
use crate::entities::customer::Customer;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// The values of a Customer that change: fields left Absent keep their value; Patch::Set(None) empties one.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct CustomerChanges {
    pub email: crate::common::Patch<Option<String>>,
    pub name: crate::common::Patch<Option<String>>,
    pub age: crate::common::Patch<Option<i64>>,
    pub balance: crate::common::Patch<Option<rust_decimal::Decimal>>,
    pub visits: crate::common::Patch<Option<i64>>,
    pub rate: crate::common::Patch<Option<f64>>,
    pub active: crate::common::Patch<Option<bool>>,
    pub address: crate::common::Patch<Option<crate::entities::customer::CustomerAddress>>,
    pub tags: crate::common::Patch<Option<Vec<String>>>,
    pub seen: crate::common::Patch<Option<chrono::DateTime<chrono::Utc>>>,
    pub r#ref: crate::common::Patch<Option<uuid::Uuid>>,
    pub photo: crate::common::Patch<Option<Vec<u8>>>,
    pub scores: crate::common::Patch<Option<mongodb::bson::Bson>>,
    pub mixed: crate::common::Patch<Option<mongodb::bson::Bson>>,
    pub nothing: crate::common::Patch<Option<mongodb::bson::Bson>>,
    pub empty: crate::common::Patch<Option<Vec<mongodb::bson::Bson>>>,
    pub deleted_at: crate::common::Patch<Option<chrono::DateTime<chrono::Utc>>>,
}

/// Operations on customers. Repositories commit every write.
pub struct CustomerService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl CustomerService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Customer after checking it.
    pub async fn create_customer(&self, customer: Customer) -> Result<Customer, DomainError> {
        let values = Values { email: customer.email.map(Some), name: customer.name.map(Some), age: customer.age.map(Some), balance: customer.balance.map(Some), visits: customer.visits.map(Some), rate: customer.rate.map(Some), active: customer.active.map(Some), address: customer.address.map(Some), tags: customer.tags.map(Some), seen: customer.seen.map(Some), r#ref: customer.r#ref.map(Some), photo: customer.photo.map(Some), scores: customer.scores.map(Some), mixed: customer.mixed.map(Some), nothing: customer.nothing.map(Some), empty: customer.empty.map(Some), deleted_at: customer.deleted_at.map(Some) };
        let uow = self.unit_of_work.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Customer::default();
        apply_values(&mut entity, &values);
        let created = uow.customers().insert(entity).await?;
        Ok(created)
    }

    /// The Customer with this key; NotFound when there is none.
    pub async fn get_customer(&self, id: String) -> Result<Customer, DomainError> {
        find(self.unit_of_work.as_ref(), id).await
    }

    /// A page of customers, by primary key.
    pub async fn list_customers(&self, offset: u64, limit: u64) -> Result<Page<Customer>, DomainError> {
        self.unit_of_work.customers().list(offset, limit).await
    }

    /// Changes the given values of a Customer.
    pub async fn update_customer(&self, id: String, changes: CustomerChanges) -> Result<Customer, DomainError> {
        let values = given(changes);
        let uow = self.unit_of_work.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.customers().update(current).await?;
        Ok(updated)
    }

    /// Marks a Customer as deleted (deletedAt); reads leave it out from then on.
    pub async fn delete_customer(&self, id: String) -> Result<(), DomainError> {
        let uow = self.unit_of_work.as_ref();
        let mut current = find(uow, id).await?;
        if !uow.orders().list_by_customer(current.id.clone().expect("id is set")).await?.is_empty() {
            return Err(DomainError::conflict("Customer", "rows of orders still point to it", &["orders"]));
        }
        current.deleted_at = Some(chrono::Utc::now());
        uow.customers().update(current).await?;
        Ok(())
    }

    /// Adds an item to tags.
    pub async fn add_tag(&self, id: String, tag: String) -> Result<Customer, DomainError> {
        let uow = self.unit_of_work.as_ref();
        find(uow, id.clone()).await?;
        let changed = uow.customers().add_tag(id.clone(), tag).await?.ok_or_else(|| DomainError::not_found("Customer", id))?;
        Ok(changed)
    }

    /// Removes an item from tags, by its value.
    pub async fn remove_tag(&self, id: String, tag: String) -> Result<Customer, DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id.clone()).await?;
        if !(current.tags.as_deref().unwrap_or_default().contains(&tag)) {
            return Err(DomainError::not_found("Tag", tag));
        }
        let changed = uow.customers().remove_tag(id.clone(), tag).await?.ok_or_else(|| DomainError::not_found("Customer", id))?;
        Ok(changed)
    }

    /// Adds an item to empty.
    pub async fn add_empty(&self, id: String, empty: mongodb::bson::Bson) -> Result<Customer, DomainError> {
        let uow = self.unit_of_work.as_ref();
        find(uow, id.clone()).await?;
        let changed = uow.customers().add_empty(id.clone(), empty).await?.ok_or_else(|| DomainError::not_found("Customer", id))?;
        Ok(changed)
    }

    /// Removes an item from empty, by its position.
    pub async fn remove_empty(&self, id: String, position: usize) -> Result<Customer, DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id.clone()).await?;
        if !(position < current.empty.as_deref().unwrap_or_default().len()) {
            return Err(DomainError::not_found("Empty", position));
        }
        let size = current.empty.as_deref().unwrap_or_default().len();
        let changed = uow.customers().remove_empty(id.clone(), position, size).await?.ok_or_else(|| DomainError::conflict("Customer", "was changed by someone else since it was read", &["empty"]))?;
        Ok(changed)
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    email: Option<Option<String>>,
    name: Option<Option<String>>,
    age: Option<Option<i64>>,
    balance: Option<Option<rust_decimal::Decimal>>,
    visits: Option<Option<i64>>,
    rate: Option<Option<f64>>,
    active: Option<Option<bool>>,
    address: Option<Option<crate::entities::customer::CustomerAddress>>,
    tags: Option<Option<Vec<String>>>,
    seen: Option<Option<chrono::DateTime<chrono::Utc>>>,
    r#ref: Option<Option<uuid::Uuid>>,
    photo: Option<Option<Vec<u8>>>,
    scores: Option<Option<mongodb::bson::Bson>>,
    mixed: Option<Option<mongodb::bson::Bson>>,
    nothing: Option<Option<mongodb::bson::Bson>>,
    empty: Option<Option<Vec<mongodb::bson::Bson>>>,
    deleted_at: Option<Option<chrono::DateTime<chrono::Utc>>>,
}

/// Checks the values against the rules of the "customers" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&Customer>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.email.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.email.is_some() {
                errors.push(FieldError::new("email", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.name.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.name.is_some() {
                errors.push(FieldError::new("name", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.rate.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.rate.is_some() {
                errors.push(FieldError::new("rate", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.active.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.active.is_some() {
                errors.push(FieldError::new("active", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.address.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.address.is_some() {
                errors.push(FieldError::new("address", "is required"));
            }
        }
        Some(value) => {
            check_customer_address(value, "address", &mut errors);
        }
    }
    match values.tags.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.tags.is_some() {
                errors.push(FieldError::new("tags", "is required"));
            }
        }
        Some(_) => {}
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Customer".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Customer>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Customer, values: &Values) {
    if let Some(value) = &values.email {
        entity.email = value.clone();
    }
    if let Some(value) = &values.name {
        entity.name = value.clone();
    }
    if let Some(value) = &values.age {
        entity.age = *value;
    }
    if let Some(value) = &values.balance {
        entity.balance = *value;
    }
    if let Some(value) = &values.visits {
        entity.visits = *value;
    }
    if let Some(value) = &values.rate {
        entity.rate = *value;
    }
    if let Some(value) = &values.active {
        entity.active = *value;
    }
    if let Some(value) = &values.address {
        entity.address = value.clone();
    }
    if let Some(value) = &values.tags {
        entity.tags = value.clone();
    }
    if let Some(value) = &values.seen {
        entity.seen = *value;
    }
    if let Some(value) = &values.r#ref {
        entity.r#ref = *value;
    }
    if let Some(value) = &values.photo {
        entity.photo = value.clone();
    }
    if let Some(value) = &values.scores {
        entity.scores = value.clone();
    }
    if let Some(value) = &values.mixed {
        entity.mixed = value.clone();
    }
    if let Some(value) = &values.nothing {
        entity.nothing = value.clone();
    }
    if let Some(value) = &values.empty {
        entity.empty = value.clone();
    }
    if let Some(value) = &values.deleted_at {
        entity.deleted_at = *value;
    }
}

/// What a CustomerAddress does not follow of its rules, each with the path of its field.
fn check_customer_address(value: &crate::entities::customer::CustomerAddress, path: &str, errors: &mut Vec<FieldError>) {
    if value.street.is_none() {
        errors.push(FieldError::new(&format!("{path}.street"), "is required"));
    }
    if value.city.is_none() {
        errors.push(FieldError::new(&format!("{path}.city"), "is required"));
    }
}

/// The values an update gives, by field.
fn given(changes: CustomerChanges) -> Values {
    Values { email: changes.email.given(), name: changes.name.given(), age: changes.age.given(), balance: changes.balance.given(), visits: changes.visits.given(), rate: changes.rate.given(), active: changes.active.given(), address: changes.address.given(), tags: changes.tags.given(), seen: changes.seen.given(), r#ref: changes.r#ref.given(), photo: changes.photo.given(), scores: changes.scores.given(), mixed: changes.mixed.given(), nothing: changes.nothing.given(), empty: changes.empty.given(), deleted_at: changes.deleted_at.given() }
}

/// The Customer with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: String) -> Result<Customer, DomainError> {
    uow.customers().find_by_id(id.clone()).await?.ok_or_else(|| DomainError::not_found("Customer", id))
}

