//! The service of the "orders" table.

use crate::common::Page;
use crate::entities::order::Order;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// The values of a Order that change: fields left Absent keep their value; Patch::Set(None) empties one.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct OrderChanges {
    pub number: crate::common::Patch<Option<i64>>,
    pub customer: crate::common::Patch<Option<String>>,
    pub seller: crate::common::Patch<Option<String>>,
    pub lines: crate::common::Patch<Option<Vec<crate::entities::order::OrderLine>>>,
}

/// Operations on orders. Repositories commit every write.
pub struct OrderService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl OrderService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Order after checking it.
    pub async fn create_order(&self, order: Order) -> Result<Order, DomainError> {
        let values = Values { number: order.number.map(Some), customer: order.customer.map(Some), seller: order.seller.map(Some), lines: order.lines.map(Some) };
        let uow = self.unit_of_work.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Order::default();
        apply_values(&mut entity, &values);
        let created = uow.orders().insert(entity).await?;
        Ok(created)
    }

    /// The Order with this key; NotFound when there is none.
    pub async fn get_order(&self, id: String) -> Result<Order, DomainError> {
        find(self.unit_of_work.as_ref(), id).await
    }

    /// A page of orders, by primary key.
    pub async fn list_orders(&self, offset: u64, limit: u64) -> Result<Page<Order>, DomainError> {
        self.unit_of_work.orders().list(offset, limit).await
    }

    /// Changes the given values of a Order.
    pub async fn update_order(&self, id: String, changes: OrderChanges) -> Result<Order, DomainError> {
        let values = given(changes);
        let uow = self.unit_of_work.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.orders().update(current).await?;
        Ok(updated)
    }

    /// Deletes a Order.
    pub async fn delete_order(&self, id: String) -> Result<(), DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id).await?;
        uow.orders().delete(&current).await?;
        Ok(())
    }

    /// The orders with this customer.
    pub async fn list_orders_by_customer(&self, customer: String) -> Result<Vec<Order>, DomainError> {
        self.unit_of_work.orders().list_by_customer(customer).await
    }

    /// Adds an item to lines.
    pub async fn add_line(&self, id: String, line: crate::entities::order::OrderLine) -> Result<Order, DomainError> {
        let mut errors: Vec<FieldError> = Vec::new();
        check_order_line(&line, "lines", &mut errors);
        if !errors.is_empty() {
            return Err(DomainError::ValidationFailed { entity: "Order".to_string(), errors });
        }
        let uow = self.unit_of_work.as_ref();
        find(uow, id.clone()).await?;
        let changed = uow.orders().add_line(id.clone(), line).await?.ok_or_else(|| DomainError::not_found("Order", id))?;
        Ok(changed)
    }

    /// Removes an item from lines, by its identifier.
    pub async fn remove_line(&self, id: String, line_id: String) -> Result<Order, DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id.clone()).await?;
        if !(current.lines.as_deref().unwrap_or_default().iter().any(|item| item.id.as_ref() == Some(&line_id))) {
            return Err(DomainError::not_found("Line", line_id));
        }
        let changed = uow.orders().remove_line(id.clone(), line_id).await?.ok_or_else(|| DomainError::not_found("Order", id))?;
        Ok(changed)
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    number: Option<Option<i64>>,
    customer: Option<Option<String>>,
    seller: Option<Option<String>>,
    lines: Option<Option<Vec<crate::entities::order::OrderLine>>>,
}

/// Checks the values against the rules of the "orders" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(uow: &dyn UnitOfWork, values: &Values, current: Option<&Order>) -> Result<(), DomainError> {
    let mut errors = Vec::new();
    if let Some(value) = values.lines.as_ref().and_then(|value| value.as_ref()) {
        for (i0, item0) in value.iter().enumerate() {
            check_order_line(item0, &format!("lines.{i0}"), &mut errors);
        }
    }
    {
        let customer = values.customer.clone().unwrap_or_else(|| current.and_then(|current| current.customer.clone()));
        if let Some(customer) = customer {
            if uow.customers().find_by_id(customer).await?.is_none() {
                errors.push(FieldError::new("customer", "no Customer has this key"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Order".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Order>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Order, values: &Values) {
    if let Some(value) = &values.number {
        entity.number = *value;
    }
    if let Some(value) = &values.customer {
        entity.customer = value.clone();
    }
    if let Some(value) = &values.seller {
        entity.seller = value.clone();
    }
    if let Some(value) = &values.lines {
        entity.lines = value.clone();
    }
}

/// What a OrderLine does not follow of its rules, each with the path of its field.
fn check_order_line(value: &crate::entities::order::OrderLine, path: &str, errors: &mut Vec<FieldError>) {
    if let Some(held) = &value.product {
        check_order_line_product(held, &format!("{path}.product"), errors);
    }
}

/// What a OrderLineProduct does not follow of its rules, each with the path of its field.
fn check_order_line_product(_value: &crate::entities::order::OrderLineProduct, _path: &str, _errors: &mut Vec<FieldError>) {
}

/// The values an update gives, by field.
fn given(changes: OrderChanges) -> Values {
    Values { number: changes.number.given(), customer: changes.customer.given(), seller: changes.seller.given(), lines: changes.lines.given() }
}

