        lines: Some(vec![new_order_line(n)]),
        ..Default::default()
    }
}

/// A stored Order.
pub async fn add_order(uow: &dyn UnitOfWork, n: i32) -> Order {
    let entity = new_order(n);
    uow.orders().insert(entity).await.expect("a stored Order")
}

/// A valid OrderLine; n makes its values differ.
pub fn new_order_line(n: i32) -> mongorust_mongodb_from_documents::entities::order::OrderLine {
    mongorust_mongodb_from_documents::entities::order::OrderLine {
        product: Some(new_order_line_product(n)),
        quantity: Some(i64::from(n)),
        note: Some(format!("note-{n}")),
        ..Default::default()
    }
}

/// A valid OrderLineProduct; n makes its values differ.
pub fn new_order_line_product(n: i32) -> mongorust_mongodb_from_documents::entities::order::OrderLineProduct {
    mongorust_mongodb_from_documents::entities::order::OrderLineProduct {
        sku: Some(format!("sku-{n}")),
        price: Some(rust_decimal::Decimal::new(i64::from(n % 10000) * 100 + 50, 2)),
        ..Default::default()
    }
}

/// A valid Customer that is not stored yet; n makes its unique values differ.
pub fn new_customer(n: i32) -> Customer {
    Customer {
        email: Some(format!("email-{n}")),
        name: Some(format!("name-{n}")),
        age: Some(i64::from(n)),
        balance: Some(rust_decimal::Decimal::new(i64::from(n % 10000) * 100 + 50, 2)),
        visits: Some(i64::from(n)),
        rate: Some(f64::from(n) + 0.5),
        active: Some(true),
        address: Some(new_customer_address(n)),
        tags: Some(Vec::new()),
        seen: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date").and_hms_opt(12, 0, 0).expect("a time").and_utc()),
        r#ref: Some(uuid::Uuid::from_u128(n as u128)),
        photo: Some(vec![n as u8]),
        scores: Some(mongodb::bson::bson!({ "n": n })),
        mixed: Some(mongodb::bson::bson!({ "n": n })),
        nothing: Some(mongodb::bson::bson!({ "n": n })),
        empty: Some(Vec::new()),
        ..Default::default()
    }
}

/// A stored Customer.
pub async fn add_customer(uow: &dyn UnitOfWork, n: i32) -> Customer {
    let entity = new_customer(n);
    uow.customers().insert(entity).await.expect("a stored Customer")
}

/// A valid CustomerAddress; n makes its values differ.
pub fn new_customer_address(n: i32) -> mongorust_mongodb_from_documents::entities::customer::CustomerAddress {
    mongorust_mongodb_from_documents::entities::customer::CustomerAddress {
        street: Some(format!("street-{n}")),
        city: Some(format!("city-{n}")),
        zip_code: Some(format!("zipcode-{n}")),
        ..Default::default()
    }
}

