//! The repository of the "orders" table, against the test database.

use mongorust_mongodb_from_documents::unit_of_work::UnitOfWork;
use super::{database, factories};

#[tokio::test]
async fn is_stored_and_read_back() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_order(&uow, 1).await;
    let found = uow.orders().find_by_id(stored.id.clone().expect("id is set")).await.expect("a read").expect("the row");
    assert_eq!(stored.id, found.id);
    if stored.customer.is_some() {
        assert_eq!(1, uow.orders().list_by_customer(stored.customer.clone().expect("customer is set")).await.expect("a read").len());
    }
}

#[tokio::test]
async fn lists_rows_by_key() {
    let (_turn, uow) = database::open().await;
    factories::add_order(&uow, 1).await;
    factories::add_order(&uow, 2).await;
    let page = uow.orders().list(0, 1).await.expect("a page");
    assert_eq!(2, page.total);
    assert_eq!(1, page.items.len());
}

#[tokio::test]
async fn is_deleted() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_order(&uow, 1).await;
    uow.orders().delete(&stored).await.expect("a delete");
    assert!(uow.orders().find_by_id(stored.id.clone().expect("id is set")).await.expect("a read").is_none());
}

#[tokio::test]
async fn adds_and_removes_one_item_of_lines() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_order(&uow, 1).await;
    let before = stored.lines.as_ref().map_or(0, Vec::len);
    let n = 7;
    let item: mongorust_mongodb_from_documents::entities::order::OrderLine = factories::new_order_line(n);
    let added = uow.orders().add_line(stored.id.clone().expect("id is set"), item).await.expect("a write").expect("the row");
    assert_eq!(before + 1, added.lines.as_ref().map_or(0, Vec::len));
    let removed = uow.orders().remove_line(stored.id.clone().expect("id is set"), added.lines.as_ref().expect("lines")[before].id.clone().expect("an identifier")).await.expect("a write").expect("the row");
    assert_eq!(before, removed.lines.as_ref().map_or(0, Vec::len));
}

