//! The service of the "orders" table, on the in-memory repositories.

use mongorust_mongodb_from_documents::errors::DomainError;
use mongorust_mongodb_from_documents::services::order::OrderService;
use mongorust_mongodb_from_documents::unit_of_work::MemoryUnitOfWork;
use std::sync::Arc;
use super::factories;

#[tokio::test]
async fn creates_a_valid_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = OrderService::new(uow.clone());
    let parent0 = factories::add_customer(uow.as_ref(), 100).await;
    let mut row = factories::new_order(1);
    row.customer = parent0.id.clone();
    let created = service.create_order(row).await.expect("a create");
    let found = service.get_order(created.id.clone().expect("id is set")).await.expect("a read");
    assert_eq!(created.id, found.id);
}

#[tokio::test]
async fn refuses_a_missing_parent() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = OrderService::new(uow.clone());
    let mut row = factories::new_order(1);
    row.customer = Some("ffffffffffffffffffffffff".to_string());
    let error = service.create_order(row).await.expect_err("a refusal");
    let DomainError::ValidationFailed { errors, .. } = &error else { panic!("{error}") };
    assert!(errors.iter().any(|error| error.field == "customer"));
}

#[tokio::test]
async fn says_when_a_row_is_missing() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = OrderService::new(uow.clone());
    assert!(matches!(service.get_order("ffffffffffffffffffffffff".to_string()).await, Err(DomainError::NotFound { .. })));
}

#[tokio::test]
async fn deletes_a_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = OrderService::new(uow.clone());
    let parent0 = factories::add_customer(uow.as_ref(), 100).await;
    let mut row = factories::new_order(1);
    row.customer = parent0.id.clone();
    let created = service.create_order(row).await.expect("a create");
    service.delete_order(created.id.clone().expect("id is set")).await.expect("a delete");
    assert!(matches!(service.get_order(created.id.clone().expect("id is set")).await, Err(DomainError::NotFound { .. })));
}

#[tokio::test]
async fn adds_and_removes_one_item_of_lines() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = OrderService::new(uow.clone());
    let parent0 = factories::add_customer(uow.as_ref(), 100).await;
    let mut row = factories::new_order(1);
    row.customer = parent0.id.clone();
    let created = service.create_order(row).await.expect("a create");
    let before = created.lines.as_ref().map_or(0, Vec::len);
    let n = 7;
    let item: mongorust_mongodb_from_documents::entities::order::OrderLine = factories::new_order_line(n);
    let added = service.add_line(created.id.clone().expect("id is set"), item).await.expect("a write");
    assert_eq!(before + 1, added.lines.as_ref().map_or(0, Vec::len));
    let removed = service.remove_line(created.id.clone().expect("id is set"), added.lines.as_ref().expect("lines")[before].id.clone().expect("an identifier")).await.expect("a write");
    assert_eq!(before, removed.lines.as_ref().map_or(0, Vec::len));
    assert!(matches!(service.remove_line(created.id.clone().expect("id is set"), "ffffffffffffffffffffffff".to_string()).await, Err(DomainError::NotFound { .. })));
}
